import { useState } from "react";
import { useEffect } from "react";
import { Link } from "wouter";
import { toast } from "sonner";
import { Archive, BookOpen, ExternalLink, FileText, FolderCog, ImagePlus, LayoutDashboard, MapPinned, Newspaper, Plus, Save, Settings2, ShieldCheck, UploadCloud, UserPlus, UsersRound } from "lucide-react";
import DashboardLayout from "@/components/DashboardLayout";
import { BackendErrorNotice } from "@/components/PublicLayout";
import { LaunchSettingsWorkspace, ManagedPagesWorkspace } from "@/components/CmsWorkspaces";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";

const modules = [
  { key: "programs", label: "Programs", icon: BookOpen, publicPath: "/programs" }, { key: "faculty", label: "Faculty", icon: UsersRound, publicPath: "/faculty" },
  { key: "facilities", label: "Facilities", icon: MapPinned, publicPath: "/facilities" }, { key: "clinicalTraining", label: "Clinical Training", icon: ShieldCheck, publicPath: "/clinical-training" },
  { key: "hospitalAffiliations", label: "Affiliations", icon: ShieldCheck, publicPath: "/clinical-training" }, { key: "galleryCategories", label: "Gallery Categories", icon: FolderCog, publicPath: "/gallery" },
  { key: "galleryImages", label: "Gallery", icon: ImagePlus, publicPath: "/gallery" }, { key: "newsArticles", label: "News & Notices", icon: Newspaper, publicPath: "/news" },
  { key: "events", label: "Events", icon: LayoutDashboard, publicPath: "/events" }, { key: "downloads", label: "Downloads", icon: FileText, publicPath: "/downloads" },
] as const;
type ModuleKey = (typeof modules)[number]["key"];
type ModuleField = { key: string; label: string; placeholder: string; type?: "text" | "textarea" | "datetime-local" | "number"; helper?: string; required?: boolean; asLines?: boolean };
const moduleFields: Record<ModuleKey, ModuleField[]> = {
  programs: [{ key: "category", label: "Program category", placeholder: "e.g. Nursing" }, { key: "duration", label: "Duration", placeholder: "e.g. To be confirmed" }, { key: "eligibility", label: "Eligibility", placeholder: "Verified eligibility details" }, { key: "clinicalTraining", label: "Clinical training note", placeholder: "Verified clinical placement information", type: "textarea" }, { key: "careerDirection", label: "Career direction", placeholder: "Verified career pathway information", type: "textarea" }, { key: "learningOutcomes", label: "Learning outcomes", placeholder: "One outcome per line", type: "textarea", asLines: true }],
  faculty: [{ key: "designation", label: "Designation", placeholder: "Faculty designation" }, { key: "qualification", label: "Qualification", placeholder: "Verified qualification" }, { key: "specialization", label: "Specialization", placeholder: "Academic specialization" }, { key: "experience", label: "Experience", placeholder: "Verified experience details" }],
  facilities: [],
  clinicalTraining: [{ key: "sectionType", label: "Section type", placeholder: "e.g. simulation-lab", required: true, helper: "A short internal content grouping label is required." }],
  hospitalAffiliations: [],
  galleryCategories: [],
  galleryImages: [{ key: "altText", label: "Image accessibility description", placeholder: "Describe what the approved image shows" }, { key: "categoryId", label: "Gallery category ID", placeholder: "Optional category number", type: "number" }],
  newsArticles: [{ key: "category", label: "Notice category", placeholder: "e.g. Academic update", required: true }, { key: "content", label: "Full notice content", placeholder: "Official published notice text", type: "textarea" }],
  events: [{ key: "location", label: "Location", placeholder: "Confirmed event location" }, { key: "startsAt", label: "Start date and time", placeholder: "", type: "datetime-local" }, { key: "endsAt", label: "End date and time", placeholder: "", type: "datetime-local" }, { key: "eventStatus", label: "Event status", placeholder: "upcoming" }],
  downloads: [{ key: "category", label: "Document category", placeholder: "e.g. Prospectus", required: true }],
};
const slugify = (value: string) => value.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
const emptyDraft = { id: undefined as number | undefined, title: "", slug: "", description: "", status: "draft", sortOrder: 0, metadata: "{}" };

export default function Admin() {
  const { user, loading } = useAuth();
  type AdminSection = ModuleKey | "pages" | "overview" | "accounts" | "settings";
  const [active, setActive] = useState<AdminSection>(() => {
    if (typeof window === "undefined") return "overview";
    const hash = window.location.hash.replace("#", "") as AdminSection;
    return ["overview", "pages", "accounts", "settings", ...modules.map(item => item.key)].includes(hash) ? hash : "overview";
  });
  useEffect(() => {
    const syncSectionFromUrl = () => {
      const hash = window.location.hash.replace("#", "") as AdminSection;
      setActive(["overview", "pages", "accounts", "settings", ...modules.map(item => item.key)].includes(hash) ? hash : "overview");
    };
    window.addEventListener("hashchange", syncSectionFromUrl);
    window.addEventListener("popstate", syncSectionFromUrl);
    return () => { window.removeEventListener("hashchange", syncSectionFromUrl); window.removeEventListener("popstate", syncSectionFromUrl); };
  }, []);
  const overview = trpc.cms.overview.useQuery(undefined, { enabled: Boolean(user && user.role !== "user") });
  if (loading) return <div className="grid min-h-screen place-items-center text-slate-600">Loading secure CMS…</div>;
  if (!user || user.role === "user") return <div className="grid min-h-screen place-items-center bg-slate-50 p-6"><div className="max-w-md rounded-3xl border border-slate-200 bg-white p-8 text-center shadow-sm"><ShieldCheck className="mx-auto h-10 w-10 text-navy" /><h1 className="mt-5 text-2xl font-bold text-navy">CMS access required</h1><p className="mt-3 text-sm leading-6 text-slate-600">Only assigned Super Admin and Content Manager accounts can access the CMS.</p></div></div>;
  const isSuperAdmin = user.role === "super_admin";
  const nav = [{ label: "Overview", path: "/admin", icon: LayoutDashboard, group: "Workspace" }, { label: "Pages", path: "/admin#pages", icon: FileText, group: "Workspace" }, ...modules.map(item => ({ label: item.label, path: `/admin#${item.key}`, icon: item.icon, group: "Content" })), ...(isSuperAdmin ? [{ label: "CMS accounts", path: "/admin#accounts", icon: UserPlus, group: "Administration" }, { label: "Settings & SEO", path: "/admin#settings", icon: Settings2, group: "Administration" }] : [])];
  const navigate = (path: string) => { const next = (path === "/admin" ? "overview" : path.split("#")[1]) as AdminSection; setActive(next); window.history.pushState(null, "", path); };
  const workspace = overview.isLoading ? <div className="institutional-notice" aria-busy="true"><div className="public-loading-orb" /><p className="mt-3">Loading your content library…</p></div> : overview.isError ? <BackendErrorNotice title="CMS content is temporarily unavailable" onRetry={() => void overview.refetch()} /> : active === "settings" && isSuperAdmin ? <><SettingsWorkspaceV2 settings={overview.data?.settings ?? []} seo={overview.data?.seo ?? []} /><AdmissionsBannerSettings settings={overview.data?.settings ?? []} /></> : active === "accounts" && isSuperAdmin ? <AccountsWorkspace /> : active === "overview" ? <DashboardOverview modules={overview.data?.modules ?? {}} onOpen={key => navigate(`/admin#${key}`)} /> : active === "pages" ? <GuidedPageWorkspace pages={overview.data?.pages ?? []} /> : <GuidedContentWorkspace module={active as ModuleKey} records={overview.data?.modules?.[active as ModuleKey] ?? []} />;
  return <DashboardLayout title="MK CMS" navigation={nav} activePath={active === "overview" ? "/admin" : `/admin#${active}`} onNavigate={navigate}><div className="mx-auto max-w-7xl space-y-8"><header className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow">Institutional content centre</p><h1 className="mt-2 text-3xl font-extrabold tracking-tight text-navy">Content management</h1><p className="mt-2 text-sm text-slate-600">Signed in as <strong>{user.name || "CMS user"}</strong> · {isSuperAdmin ? "Super Admin" : "Content Manager"}</p></div><div className="rounded-xl bg-teal-50 px-4 py-3 text-sm font-semibold text-teal-800">{isSuperAdmin ? "Settings, SEO, and account controls available" : "Content publishing controls available"}</div></header>{workspace}</div></DashboardLayout>;
}

function AccountsWorkspace() {
  const utils = trpc.useUtils();
  const { data: accounts = [], isLoading } = trpc.cms.accounts.list.useQuery();
  const create = trpc.cms.accounts.createContentManager.useMutation({ onSuccess: () => { toast.success("Content Manager account created"); utils.cms.accounts.list.invalidate(); setDraft({ name: "", email: "", password: "" }); }, onError: error => toast.error(error.message) });
  const setActive = trpc.cms.accounts.setContentManagerActive.useMutation({ onSuccess: account => { toast.success(`${account?.name || "Content Manager"} access updated`); utils.cms.accounts.list.invalidate(); }, onError: error => toast.error(error.message) });
  const resetPassword = trpc.cms.accounts.resetContentManagerPassword.useMutation({ onSuccess: account => { toast.success(`Password reset for ${account?.name || "Content Manager"}`); utils.cms.accounts.list.invalidate(); setResettingId(null); setNewPassword(""); }, onError: error => toast.error(error.message) });
  const [draft, setDraft] = useState({ name: "", email: "", password: "" });
  const [resettingId, setResettingId] = useState<number | null>(null); const [newPassword, setNewPassword] = useState("");
  return <section className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><p className="eyebrow">Super Admin</p><h2 className="mt-1 text-xl font-bold text-navy">Create Content Manager</h2><p className="mt-2 text-sm leading-6 text-slate-600">Give trusted staff their own CMS sign-in. Content Managers can publish content, but cannot manage accounts, Settings, or SEO.</p><div className="mt-6 grid gap-4"><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Full name<Input value={draft.name} onChange={event => setDraft({ ...draft, name: event.target.value })} autoComplete="name" /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Email address<Input type="email" value={draft.email} onChange={event => setDraft({ ...draft, email: event.target.value })} autoComplete="email" /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Temporary password<Input type="password" value={draft.password} onChange={event => setDraft({ ...draft, password: event.target.value })} minLength={12} autoComplete="new-password" /><span className="text-xs font-normal text-slate-500">At least 12 characters. Share it securely; it is never displayed again.</span></label><Button disabled={create.isPending || !draft.name || !draft.email || draft.password.length < 12} onClick={() => create.mutate(draft)}><UserPlus className="h-4 w-4" />{create.isPending ? "Creating account…" : "Create Content Manager"}</Button></div></div><div className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="border-b border-slate-100 p-6"><p className="eyebrow">Account directory</p><h2 className="mt-1 text-xl font-bold text-navy">CMS accounts</h2><p className="mt-2 text-sm text-slate-600">Super Admins can create, suspend, reactivate, and reset Content Manager credentials. Each user signs in independently at <strong>/cms-login</strong>.</p></div>{isLoading ? <div className="p-8 text-sm text-slate-600">Loading accounts…</div> : accounts.length ? <div className="divide-y divide-slate-100">{accounts.map(account => { const isManager = account.role === "content_manager"; const isResetting = resettingId === account.id; return <div key={account.id} className="p-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-bold text-navy">{account.name || "CMS account"}</p><p className="mt-1 text-sm text-slate-500">{account.email}</p></div><div className="flex flex-wrap items-center gap-2"><span className={`rounded-full px-3 py-1 text-xs font-bold ${account.role === "super_admin" ? "bg-navy text-white" : "bg-teal-50 text-teal-800"}`}>{account.role === "super_admin" ? "Super Admin" : "Content Manager"}</span><span className={`rounded-full px-3 py-1 text-xs font-bold ${account.isActive ? "bg-emerald-50 text-emerald-800" : "bg-amber-50 text-amber-800"}`}>{account.isActive ? "Active" : "Suspended"}</span></div></div>{isManager ? <div className="mt-4 flex flex-col gap-3 border-t border-slate-100 pt-4 sm:flex-row sm:items-center"><Button size="sm" variant="outline" disabled={setActive.isPending} onClick={() => setActive.mutate({ id: account.id, isActive: !account.isActive })}>{account.isActive ? "Suspend publishing access" : "Reactivate publishing access"}</Button><Button size="sm" variant="outline" disabled={resetPassword.isPending} onClick={() => { setResettingId(isResetting ? null : account.id); setNewPassword(""); }}>{isResetting ? "Cancel password reset" : "Reset password"}</Button></div> : null}{isManager && isResetting ? <div className="mt-3 flex flex-col gap-3 rounded-xl bg-slate-50 p-4 sm:flex-row sm:items-end"><label className="grid flex-1 gap-1.5 text-sm font-semibold text-slate-700">New temporary password<Input type="password" value={newPassword} onChange={event => setNewPassword(event.target.value)} minLength={12} autoComplete="new-password" /><span className="text-xs font-normal text-slate-500">Use at least 12 characters and share it securely.</span></label><Button size="sm" disabled={resetPassword.isPending || newPassword.length < 12} onClick={() => resetPassword.mutate({ id: account.id, password: newPassword })}>{resetPassword.isPending ? "Resetting…" : "Save new password"}</Button></div> : null}</div>; })}</div> : <div className="p-8 text-sm text-slate-600">No CMS accounts found.</div>}</div></section>;
}

function SettingsWorkspaceV2({ settings, seo }: { settings: any[]; seo: any[] }) {
  return <LaunchSettingsWorkspace settings={settings} seo={seo} />;
  const utils = trpc.useUtils();
  const save = trpc.cms.settings.upsert.useMutation({ onSuccess: () => { toast.success("Settings saved and stored permanently"); utils.cms.overview.invalidate(); utils.public.snapshot.invalidate(); }, onError: error => toast.error(error.message) });
  const saveSeo = trpc.cms.seo.upsert.useMutation({ onSuccess: () => { toast.success("SEO settings saved"); utils.cms.overview.invalidate(); }, onError: error => toast.error(error.message) });
  const find = (key: string) => settings.find(setting => setting.key === key);
  const identityRecord = find("identity"); const contactRecord = find("contact");
  const [identity, setIdentity] = useState<Record<string, string>>(() => ({ name: String(identityRecord?.value?.name || ""), tagline: String(identityRecord?.value?.tagline || "") }));
  const [contact, setContact] = useState<Record<string, string>>(() => ({ phone: String(contactRecord?.value?.phone || ""), whatsapp: String(contactRecord?.value?.whatsapp || ""), email: String(contactRecord?.value?.email || ""), address: String(contactRecord?.value?.address || ""), officeHours: String(contactRecord?.value?.officeHours || ""), mapLatitude: String(contactRecord?.value?.mapLatitude || ""), mapLongitude: String(contactRecord?.value?.mapLongitude || "") }));
  const [seoDraft, setSeoDraft] = useState({ path: seo[0]?.path || "/", title: seo[0]?.title || "", description: seo[0]?.description || "", canonicalUrl: seo[0]?.canonicalUrl || "", ogImageUrl: seo[0]?.ogImageUrl || "", indexable: seo[0]?.indexable ?? true });
  const persist = (record: any, value: Record<string, string>) => { if (!record) return toast.error("This setting is not available yet"); save.mutate({ key: record.key, label: record.label, description: record.description || undefined, value }); };
  return <div className="space-y-6"><section className="grid gap-6 lg:grid-cols-2"><div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><p className="eyebrow">Institute profile</p><h2 className="mt-1 text-xl font-bold text-navy">Identity</h2><p className="mt-2 text-sm text-slate-600">These details appear across the public website.</p><div className="mt-6 grid gap-4"><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Institute name<Input value={identity.name} onChange={event => setIdentity({ ...identity, name: event.target.value })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Short tagline<Input value={identity.tagline} onChange={event => setIdentity({ ...identity, tagline: event.target.value })} /></label><Button disabled={save.isPending} onClick={() => persist(identityRecord, identity)}><Save className="h-4 w-4" />Save identity</Button></div></div><div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><p className="eyebrow">Contact centre</p><h2 className="mt-1 text-xl font-bold text-navy">Contact details</h2><p className="mt-2 text-sm text-slate-600">Only enter approved public contact information.</p><div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Phone<Input value={contact.phone} onChange={event => setContact({ ...contact, phone: event.target.value })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">WhatsApp<Input value={contact.whatsapp} onChange={event => setContact({ ...contact, whatsapp: event.target.value })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700 sm:col-span-2">Email<Input type="email" value={contact.email} onChange={event => setContact({ ...contact, email: event.target.value })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700 sm:col-span-2">Address<Textarea value={contact.address} onChange={event => setContact({ ...contact, address: event.target.value })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Office hours<Input value={contact.officeHours} onChange={event => setContact({ ...contact, officeHours: event.target.value })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Map latitude<Input value={contact.mapLatitude} onChange={event => setContact({ ...contact, mapLatitude: event.target.value })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Map longitude<Input value={contact.mapLongitude} onChange={event => setContact({ ...contact, mapLongitude: event.target.value })} /></label><Button className="sm:col-span-2" disabled={save.isPending} onClick={() => persist(contactRecord, contact)}><Save className="h-4 w-4" />Save contact details</Button></div></div></section><section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><p className="eyebrow">Search visibility</p><h2 className="mt-1 text-xl font-bold text-navy">Page SEO</h2><div className="mt-6 grid gap-4 md:grid-cols-2"><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Page path<Input value={seoDraft.path} onChange={event => setSeoDraft({ ...seoDraft, path: event.target.value })} placeholder="/about" /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">SEO title<Input value={seoDraft.title} onChange={event => setSeoDraft({ ...seoDraft, title: event.target.value })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700 md:col-span-2">SEO description<Textarea value={seoDraft.description} onChange={event => setSeoDraft({ ...seoDraft, description: event.target.value })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700 md:col-span-2">Canonical URL (optional)<Input value={seoDraft.canonicalUrl} onChange={event => setSeoDraft({ ...seoDraft, canonicalUrl: event.target.value })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700 md:col-span-2">Social image URL (optional)<Input value={seoDraft.ogImageUrl} onChange={event => setSeoDraft({ ...seoDraft, ogImageUrl: event.target.value })} /></label><label className="flex items-center gap-2 text-sm font-semibold text-slate-700"><input type="checkbox" checked={seoDraft.indexable} onChange={event => setSeoDraft({ ...seoDraft, indexable: event.target.checked })} />Allow search indexing</label></div><Button className="mt-5" disabled={saveSeo.isPending} onClick={() => saveSeo.mutate(seoDraft)}><Save className="h-4 w-4" />Save SEO settings</Button></section></div>;
}

function AdmissionsBannerSettings({ settings }: { settings: any[] }) {
  const utils = trpc.useUtils(); const record = settings.find(setting => setting.key === "admissions_banner"); const initial = record?.value || {}; const [banner, setBanner] = useState({ enabled: Boolean(initial.enabled), eyebrow: String(initial.eyebrow || "Admissions update"), title: String(initial.title || ""), message: String(initial.message || ""), ctaLabel: String(initial.ctaLabel || ""), ctaUrl: String(initial.ctaUrl || "/admissions") });
  const save = trpc.cms.settings.upsert.useMutation({ onSuccess: () => { toast.success("Admissions banner saved"); utils.cms.overview.invalidate(); utils.public.snapshot.invalidate(); }, onError: error => toast.error(error.message) });
  return <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><p className="eyebrow">Admissions communications</p><h2 className="mt-1 text-xl font-bold text-navy">Important dates banner</h2><p className="mt-2 text-sm leading-6 text-slate-600">This banner is hidden from the public site until it is enabled and both a title and message are approved.</p><div className="mt-6 grid gap-4 md:grid-cols-2"><label className="flex items-center gap-2 text-sm font-semibold text-slate-700 md:col-span-2"><input type="checkbox" checked={banner.enabled} onChange={event => setBanner({ ...banner, enabled: event.target.checked })} />Show this approved banner on public pages</label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Short label<Input value={banner.eyebrow} onChange={event => setBanner({ ...banner, eyebrow: event.target.value })} placeholder="Admissions update" /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Banner title<Input value={banner.title} onChange={event => setBanner({ ...banner, title: event.target.value })} placeholder="Approved announcement title" /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700 md:col-span-2">Banner message<Textarea value={banner.message} onChange={event => setBanner({ ...banner, message: event.target.value })} placeholder="Approved dates or admissions information" /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Button label (optional)<Input value={banner.ctaLabel} onChange={event => setBanner({ ...banner, ctaLabel: event.target.value })} placeholder="Admissions information" /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Button link<Input value={banner.ctaUrl} onChange={event => setBanner({ ...banner, ctaUrl: event.target.value })} placeholder="/admissions" /></label></div><Button className="mt-5" disabled={save.isPending} onClick={() => save.mutate({ key: "admissions_banner", label: "Admissions and important dates banner", description: "Super Admin-controlled public admissions or important dates announcement.", value: banner })}><Save className="h-4 w-4" />{save.isPending ? "Saving…" : "Save admissions banner"}</Button></section>;
}

function DashboardOverview({ modules: values, onOpen }: { modules: Record<string, any[]>; onOpen: (module: ModuleKey) => void }) {
  return <><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{modules.slice(0, 4).map(item => <button key={item.key} onClick={() => onOpen(item.key)} className="rounded-2xl border border-slate-200 bg-white p-5 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-teal-300"><item.icon className="h-6 w-6 text-teal-700" /><p className="mt-7 text-3xl font-extrabold text-navy">{(values[item.key] ?? []).length}</p><p className="mt-1 text-sm font-semibold text-slate-600">{item.label}</p></button>)}</section><section className="mt-8 grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><div className="rounded-2xl border border-slate-200 bg-white p-7 shadow-sm"><p className="eyebrow">Publishing workflow</p><h2 className="mt-2 text-xl font-bold text-navy">Keep the public information centre current</h2><div className="mt-6 grid gap-4 text-sm text-slate-600"><p><strong className="text-navy">1. Prepare:</strong> Save entries as drafts while collecting confirmed institutional information and approved media.</p><p><strong className="text-navy">2. Review:</strong> Check titles, slugs, accessibility descriptions, order, and required module fields.</p><p><strong className="text-navy">3. Publish:</strong> Publish only content ready for students, families, and prospective applicants to view.</p><p><strong className="text-navy">4. Persist:</strong> CMS changes are stored in the database and remain through normal code updates and restarts. Only an intentionally destructive database migration can remove content.</p></div></div><div className="rounded-2xl bg-navy p-7 text-white"><p className="eyebrow text-gold-200">Quality standard</p><h2 className="mt-2 text-xl font-bold">Publish only verified information</h2><p className="mt-4 text-sm leading-6 text-slate-300">The public website intentionally excludes drafts and archived items. Use the preview links in each content area to review the student-facing result after publishing.</p></div></section></>;
}

function ContentWorkspace({ module, records }: { module: ModuleKey; records: any[] }) {
  const utils = trpc.useUtils(); const save = trpc.cms.save.useMutation({ onSuccess: () => { toast.success("Content saved"); utils.cms.overview.invalidate(); }, onError: error => toast.error(error.message) }); const setStatus = trpc.cms.setStatus.useMutation({ onSuccess: () => { toast.success("Publishing status updated"); utils.cms.overview.invalidate(); }, onError: error => toast.error(error.message) }); const upload = trpc.cms.uploadMedia.useMutation({ onError: error => toast.error(error.message) }); const [draft, setDraft] = useState(emptyDraft); const [fields, setFields] = useState<Record<string, string>>({}); const label = modules.find(item => item.key === module)?.label || module; const publicPath = modules.find(item => item.key === module)?.publicPath || "/";
  const patchMetadata = (patch: Record<string, string>) => { try { setDraft(current => ({ ...current, metadata: JSON.stringify({ ...JSON.parse(current.metadata || "{}"), ...patch }, null, 2) })); } catch { setDraft(current => ({ ...current, metadata: JSON.stringify(patch, null, 2) })); } };
  const uploadFile = (file?: File) => { if (!file) return; if (file.size > 10_000_000) { toast.error("Files must be 10 MB or smaller"); return; } const reader = new FileReader(); reader.onload = () => { const dataBase64 = String(reader.result).split(",")[1] || ""; upload.mutate({ fileName: file.name, mimeType: file.type || "application/octet-stream", dataBase64, scope: module === "downloads" ? "document" : "image" }, { onSuccess: result => { patchMetadata(module === "downloads" ? { fileUrl: result.url, fileKey: result.key } : { mediaUrl: result.url, mediaKey: result.key, featuredImageUrl: result.url, featuredImageKey: result.key, photoUrl: result.url, photoKey: result.key, imageUrl: result.url }); toast.success("File uploaded securely to the media library"); } }); }; reader.readAsDataURL(file); };
  const saveRecord = () => { if (!draft.title.trim()) { toast.error("Enter a title before saving"); return; } if (!draft.slug.trim() && module !== "hospitalAffiliations" && module !== "galleryImages") { toast.error("Enter a public URL slug before saving"); return; } const missing = moduleFields[module].find(field => field.required && !fields[field.key]?.trim()); if (missing) { toast.error(`${missing.label} is required`); return; } let metadata: Record<string, unknown>; try { metadata = JSON.parse(draft.metadata || "{}"); } catch { toast.error("Advanced fields must be valid JSON"); return; } moduleFields[module].forEach(field => { const value = fields[field.key]?.trim(); if (value) metadata[field.key] = field.asLines ? value.split("\n").map(line => line.trim()).filter(Boolean) : field.type === "number" ? Number(value) : value; }); save.mutate({ module, record: { id: draft.id, title: draft.title.trim(), slug: draft.slug.trim() || slugify(draft.title), description: draft.description.trim() || null, status: draft.status as "draft" | "published", sortOrder: draft.sortOrder, metadata } }, { onSuccess: () => { setDraft({ ...emptyDraft, sortOrder: records.length }); setFields({}); } }); };
  const editRecord = (record: any) => { const initial: Record<string, string> = {}; moduleFields[module].forEach(field => { const value = record[field.key]; initial[field.key] = Array.isArray(value) ? value.join("\n") : value === undefined || value === null ? "" : String(value); }); setFields(initial); setDraft({ id: record.id, title: record.title || record.name || record.caption || "", slug: record.slug || slugify(record.title || record.name || record.caption || ""), description: record.description || record.overview || record.biography || record.excerpt || "", status: record.status || "draft", sortOrder: record.sortOrder || 0, metadata: JSON.stringify(record, null, 2) }); };
  return <section className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex items-start justify-between gap-3"><div><p className="eyebrow">{draft.id ? "Edit content" : "Create content"}</p><h2 className="mt-1 text-xl font-bold text-navy">{draft.id ? `Edit ${label}` : `Add ${label}`}</h2><p className="mt-2 text-sm leading-6 text-slate-600">Use the guided fields first. Advanced fields are available only for module-specific refinements.</p></div><Link href={publicPath} target="_blank" className="rounded-lg border border-slate-200 p-2 text-navy hover:bg-teal-50" aria-label={`Preview ${label}`}><ExternalLink className="h-4 w-4" /></Link></div><div className="mt-6 grid gap-4"><Input aria-label="Title" placeholder="Title" value={draft.title} onChange={event => setDraft(current => ({ ...current, title: event.target.value, slug: current.id || current.slug ? current.slug : slugify(event.target.value) }))} /><Input aria-label="URL slug" placeholder="Public URL slug" value={draft.slug} onChange={event => setDraft({ ...draft, slug: slugify(event.target.value) })} /><Textarea aria-label="Description or overview" placeholder="Description or overview" value={draft.description} onChange={event => setDraft({ ...draft, description: event.target.value })} />{moduleFields[module].map(field => <label key={field.key} className="grid gap-1.5 text-sm font-semibold text-slate-700">{field.label}{field.required ? <span className="text-teal-700">Required</span> : null}{field.type === "textarea" ? <Textarea placeholder={field.placeholder} value={fields[field.key] || ""} onChange={event => setFields({ ...fields, [field.key]: event.target.value })} /> : <Input type={field.type || "text"} placeholder={field.placeholder} value={fields[field.key] || ""} onChange={event => setFields({ ...fields, [field.key]: event.target.value })} />}{field.helper ? <span className="text-xs font-normal leading-5 text-slate-500">{field.helper}</span> : null}</label>)}<div className="grid gap-4 sm:grid-cols-2"><select className="field-input" aria-label="Publishing status" value={draft.status} onChange={event => setDraft({ ...draft, status: event.target.value })}><option value="draft">Draft — private</option><option value="published">Published — public</option></select><Input aria-label="Display order" type="number" min="0" placeholder="Display order" value={draft.sortOrder} onChange={event => setDraft({ ...draft, sortOrder: Number(event.target.value) || 0 })} /></div><label className="flex min-h-11 items-center justify-center gap-2 rounded-xl border border-dashed border-teal-300 bg-teal-50 px-4 text-sm font-bold text-teal-800 hover:bg-teal-100"><UploadCloud className="h-4 w-4" />{upload.isPending ? "Uploading…" : "Upload approved file"}<input type="file" className="sr-only" accept={module === "downloads" ? ".pdf,.doc,.docx,.xls,.xlsx" : "image/*"} onChange={event => uploadFile(event.target.files?.[0])} /></label><details className="rounded-xl border border-slate-200 bg-slate-50 p-4"><summary className="cursor-pointer text-sm font-bold text-navy">Advanced module fields (JSON)</summary><p className="mt-2 text-xs leading-5 text-slate-500">Use only for fields not represented above. S3 URLs and storage keys are inserted automatically after upload.</p><Textarea className="mt-3 min-h-28 font-mono text-xs" value={draft.metadata} onChange={event => setDraft({ ...draft, metadata: event.target.value })} /></details><Button onClick={saveRecord} disabled={save.isPending} className="gap-2"><Save className="h-4 w-4" />{draft.id ? "Update" : "Save"} {label}</Button></div></div><div className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between border-b border-slate-100 p-6"><div><p className="eyebrow">Library</p><h2 className="mt-1 text-xl font-bold text-navy">{label}</h2></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold text-slate-600">{records.length} items</span></div>{records.length ? <div className="divide-y divide-slate-100">{records.map(record => <div key={record.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><button type="button" onClick={() => editRecord(record)} className="min-w-0 text-left"><h3 className="truncate font-bold text-navy">{record.title || record.name || record.caption}</h3><p className="mt-1 text-sm text-slate-500">/{record.slug || "media-item"} · order {record.sortOrder ?? 0} · <span className="capitalize">{record.status}</span></p></button><div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => setStatus.mutate({ module, id: record.id, status: record.status === "published" ? "draft" : "published" })}>{record.status === "published" ? "Unpublish" : "Publish"}</Button><Button size="sm" variant="outline" className="text-slate-600" onClick={() => setStatus.mutate({ module, id: record.id, status: "archived" })} aria-label="Archive item"><Archive className="h-3.5 w-3.5" /></Button></div></div>)}</div> : <div className="p-10 text-center"><FolderCog className="mx-auto h-7 w-7 text-slate-400" /><p className="mt-3 text-sm text-slate-600">No {label.toLowerCase()} have been added.</p><p className="mt-1 text-xs text-slate-500">Create a draft when your information is ready for review.</p></div>}</div></section>;
}

function GuidedPageWorkspace({ pages }: { pages: any[] }) {
  return <ManagedPagesWorkspace pages={pages} />;
  const utils = trpc.useUtils(); const save = trpc.cms.savePage.useMutation({ onSuccess: () => { toast.success("Page saved"); utils.cms.overview.invalidate(); setDraft({ title: "", slug: "", description: "", sectionOneTitle: "", sectionOneDescription: "", sectionTwoTitle: "", sectionTwoDescription: "", status: "draft" }); }, onError: error => toast.error(error.message) });
  const [draft, setDraft] = useState({ title: "", slug: "", description: "", sectionOneTitle: "", sectionOneDescription: "", sectionTwoTitle: "", sectionTwoDescription: "", status: "draft" });
  const savePage = () => { if (!draft.title.trim() || !draft.slug.trim()) return toast.error("Add a page title and public URL"); const blocks = [{ title: draft.sectionOneTitle, description: draft.sectionOneDescription }, { title: draft.sectionTwoTitle, description: draft.sectionTwoDescription }].filter(block => block.title.trim() || block.description.trim()); save.mutate({ title: draft.title.trim(), slug: slugify(draft.slug), sections: { description: draft.description, blocks }, status: draft.status as "draft" | "published", sortOrder: pages.length, indexable: true }); };
  return <section className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><p className="eyebrow">Guided page builder</p><h2 className="mt-1 text-xl font-bold text-navy">Create an information page</h2><p className="mt-2 text-sm leading-6 text-slate-600">Use simple fields for Home, About, Student Life, and other editorial pages. No JSON is required.</p><div className="mt-6 grid gap-4"><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Page title<Input value={draft.title} onChange={event => setDraft({ ...draft, title: event.target.value, slug: draft.slug || slugify(event.target.value) })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Public URL<Input value={draft.slug} onChange={event => setDraft({ ...draft, slug: slugify(event.target.value) })} placeholder="about" /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Page introduction<Textarea value={draft.description} onChange={event => setDraft({ ...draft, description: event.target.value })} /></label><div className="rounded-xl border border-slate-200 bg-slate-50 p-4"><p className="text-sm font-bold text-navy">First highlight</p><Input className="mt-3" placeholder="Highlight title" value={draft.sectionOneTitle} onChange={event => setDraft({ ...draft, sectionOneTitle: event.target.value })} /><Textarea className="mt-3" placeholder="Highlight description" value={draft.sectionOneDescription} onChange={event => setDraft({ ...draft, sectionOneDescription: event.target.value })} /></div><div className="rounded-xl border border-slate-200 bg-slate-50 p-4"><p className="text-sm font-bold text-navy">Second highlight</p><Input className="mt-3" placeholder="Highlight title" value={draft.sectionTwoTitle} onChange={event => setDraft({ ...draft, sectionTwoTitle: event.target.value })} /><Textarea className="mt-3" placeholder="Highlight description" value={draft.sectionTwoDescription} onChange={event => setDraft({ ...draft, sectionTwoDescription: event.target.value })} /></div><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Visibility<select className="field-input" value={draft.status} onChange={event => setDraft({ ...draft, status: event.target.value })}><option value="draft">Draft — private</option><option value="published">Published — public</option></select></label><Button onClick={savePage} disabled={save.isPending}><Save className="h-4 w-4" />{save.isPending ? "Saving…" : "Save page"}</Button></div></div><div className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="border-b border-slate-100 p-6"><p className="eyebrow">Page library</p><h2 className="mt-1 text-xl font-bold text-navy">Existing pages</h2></div>{pages.length ? <div className="divide-y divide-slate-100">{pages.map(page => <div key={page.id} className="flex items-center justify-between gap-3 p-5"><div><h3 className="font-bold text-navy">{page.title}</h3><p className="mt-1 text-sm text-slate-500">/{page.slug} · {page.status}</p></div><Link href={`/${page.slug}`} target="_blank" className="rounded-lg border border-slate-200 p-2 text-navy hover:bg-teal-50" aria-label={`Preview ${page.title}`}><ExternalLink className="h-4 w-4" /></Link></div>)}</div> : <div className="p-10 text-center text-sm text-slate-600">No CMS pages created yet.</div>}</div></section>;
}

function GuidedContentWorkspace({ module, records }: { module: ModuleKey; records: any[] }) {
  const utils = trpc.useUtils(); const save = trpc.cms.save.useMutation({ onSuccess: () => { toast.success("Content saved"); utils.cms.overview.invalidate(); reset(); }, onError: error => toast.error(error.message) }); const setStatus = trpc.cms.setStatus.useMutation({ onSuccess: () => { toast.success("Publishing status updated"); utils.cms.overview.invalidate(); }, onError: error => toast.error(error.message) }); const upload = trpc.cms.uploadMedia.useMutation({ onError: error => toast.error(error.message) });
  const label = modules.find(item => item.key === module)?.label || module; const publicPath = modules.find(item => item.key === module)?.publicPath || "/"; const [draft, setDraft] = useState({ id: undefined as number | undefined, title: "", slug: "", description: "", status: "draft", sortOrder: records.length }); const [fields, setFields] = useState<Record<string, string>>({}); const [metadata, setMetadata] = useState<Record<string, unknown>>({});
  const reset = () => { setDraft({ id: undefined, title: "", slug: "", description: "", status: "draft", sortOrder: records.length }); setFields({}); setMetadata({}); };
  const edit = (record: any) => { const nextFields: Record<string, string> = {}; moduleFields[module].forEach(field => { const value = record[field.key]; nextFields[field.key] = Array.isArray(value) ? value.join("\n") : value === undefined || value === null ? "" : String(value); }); setFields(nextFields); setMetadata({ ...record }); setDraft({ id: record.id, title: record.title || record.name || record.caption || "", slug: record.slug || slugify(record.title || record.name || record.caption || ""), description: record.description || record.overview || record.biography || record.excerpt || "", status: record.status || "draft", sortOrder: record.sortOrder ?? 0 }); };
  const uploadFile = (file?: File) => { if (!file) return; if (file.size > 10_000_000) return toast.error("Files must be 10 MB or smaller"); const reader = new FileReader(); reader.onload = () => upload.mutate({ fileName: file.name, mimeType: file.type || "application/octet-stream", dataBase64: String(reader.result).split(",")[1] || "", scope: module === "downloads" ? "document" : "image" }, { onSuccess: result => { setMetadata(current => ({ ...current, ...(module === "downloads" ? { fileUrl: result.url, fileKey: result.key } : { mediaUrl: result.url, mediaKey: result.key, featuredImageUrl: result.url, featuredImageKey: result.key, photoUrl: result.url, photoKey: result.key, imageUrl: result.url } ) })); toast.success("File uploaded securely"); } }); reader.readAsDataURL(file); };
  const submit = () => { if (!draft.title.trim()) return toast.error("Enter a title before saving"); const recordSlug = draft.slug.trim() || slugify(draft.title); if (!recordSlug) return toast.error("Enter a title or public URL before saving"); const missing = moduleFields[module].find(field => field.required && !fields[field.key]?.trim()); if (missing) return toast.error(`${missing.label} is required`); const nextMetadata: Record<string, unknown> = { ...metadata }; moduleFields[module].forEach(field => { const value = fields[field.key]?.trim(); if (value) nextMetadata[field.key] = field.asLines ? value.split("\n").map(line => line.trim()).filter(Boolean) : field.type === "number" ? Number(value) : value; }); save.mutate({ module, record: { id: draft.id, title: draft.title.trim(), slug: recordSlug, description: draft.description.trim() || null, status: draft.status as "draft" | "published", sortOrder: draft.sortOrder, metadata: nextMetadata } }); };
  return <section className="grid gap-6 xl:grid-cols-[.85fr_1.15fr]"><div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex items-start justify-between gap-3"><div><p className="eyebrow">{draft.id ? "Edit content" : "Create content"}</p><h2 className="mt-1 text-xl font-bold text-navy">{draft.id ? `Edit ${label}` : `Add ${label}`}</h2><p className="mt-2 text-sm leading-6 text-slate-600">1. Save a private draft. 2. Preview it. 3. Publish only approved information.</p></div><div className="flex gap-2">{draft.id ? <><Button size="sm" variant="outline" onClick={reset}>New record</Button><a href={`/cms-preview/${module}/${draft.id}`} target="_blank" rel="noreferrer" className="inline-flex h-9 items-center gap-1 rounded-md border border-slate-200 px-2 text-sm font-semibold text-navy hover:bg-teal-50"><ExternalLink className="h-4 w-4" />Preview</a></> : null}<Link href={publicPath} target="_blank" className="rounded-lg border border-slate-200 p-2 text-navy hover:bg-teal-50" aria-label={`View published ${label} listing`}><ExternalLink className="h-4 w-4" /></Link></div></div><div className="mt-6 grid gap-4"><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Title<Input value={draft.title} onChange={event => setDraft(current => ({ ...current, title: event.target.value, slug: current.id || current.slug ? current.slug : slugify(event.target.value) }))} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Public URL<Input value={draft.slug} onChange={event => setDraft({ ...draft, slug: slugify(event.target.value) })} /></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Description or overview<Textarea value={draft.description} onChange={event => setDraft({ ...draft, description: event.target.value })} /></label>{moduleFields[module].map(field => <label key={field.key} className="grid gap-1.5 text-sm font-semibold text-slate-700">{field.label}{field.required ? <span className="text-teal-700">Required</span> : null}{field.type === "textarea" ? <Textarea placeholder={field.placeholder} value={fields[field.key] || ""} onChange={event => setFields({ ...fields, [field.key]: event.target.value })} /> : <Input type={field.type || "text"} placeholder={field.placeholder} value={fields[field.key] || ""} onChange={event => setFields({ ...fields, [field.key]: event.target.value })} />}{field.helper ? <span className="text-xs font-normal text-slate-500">{field.helper}</span> : null}</label>)}<div className="grid gap-4 sm:grid-cols-2"><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Visibility<select className="field-input" value={draft.status} onChange={event => setDraft({ ...draft, status: event.target.value })}><option value="draft">Draft — private</option><option value="published">Published — public</option></select></label><label className="grid gap-1.5 text-sm font-semibold text-slate-700">Display order<Input type="number" min="0" value={draft.sortOrder} onChange={event => setDraft({ ...draft, sortOrder: Number(event.target.value) || 0 })} /></label></div><label className="flex min-h-11 items-center justify-center gap-2 rounded-xl border border-dashed border-teal-300 bg-teal-50 px-4 text-sm font-bold text-teal-800 hover:bg-teal-100"><UploadCloud className="h-4 w-4" />{upload.isPending ? "Uploading…" : "Upload approved file"}<input type="file" className="sr-only" accept={module === "downloads" ? ".pdf,.doc,.docx,.xls,.xlsx" : "image/*"} onChange={event => uploadFile(event.target.files?.[0])} /></label><Button onClick={submit} disabled={save.isPending} className="gap-2"><Save className="h-4 w-4" />{save.isPending ? "Saving…" : draft.status === "published" ? "Save & publish" : "Save private draft"}</Button></div></div><div className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between border-b border-slate-100 p-6"><div><p className="eyebrow">Library</p><h2 className="mt-1 text-xl font-bold text-navy">{label}</h2></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold text-slate-600">{records.length} items</span></div>{records.length ? <div className="divide-y divide-slate-100">{records.map(record => <div key={record.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><button type="button" onClick={() => edit(record)} className="min-w-0 text-left"><h3 className="truncate font-bold text-navy">{record.title || record.name || record.caption}</h3><p className="mt-1 text-sm text-slate-500">/{record.slug || "media-item"} · order {record.sortOrder ?? 0} · <span className="capitalize">{record.status}</span></p></button><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => edit(record)}>Edit</Button><a href={`/cms-preview/${module}/${record.id}`} target="_blank" rel="noreferrer" className="inline-flex h-9 items-center justify-center rounded-md border border-slate-200 px-2 text-navy hover:bg-teal-50" aria-label={`Securely preview ${record.title || record.name || record.caption}`} title="Secure preview"><ExternalLink className="h-4 w-4" /></a><Button size="sm" variant="outline" onClick={() => setStatus.mutate({ module, id: record.id, status: record.status === "published" ? "draft" : "published" })}>{record.status === "published" ? "Unpublish" : "Publish"}</Button><Button size="sm" variant="outline" className="text-slate-600" onClick={() => setStatus.mutate({ module, id: record.id, status: "archived" })} aria-label="Archive item"><Archive className="h-3.5 w-3.5" /></Button></div></div>)}</div> : <div className="p-10 text-center"><FolderCog className="mx-auto h-7 w-7 text-slate-400" /><p className="mt-3 text-sm text-slate-600">No {label.toLowerCase()} have been added.</p><p className="mt-1 text-xs text-slate-500">Create a draft when your information is ready for review.</p></div>}</div></section>;
}

function SettingsWorkspace({ settings, seo }: { settings: any[]; seo: any[] }) { const utils = trpc.useUtils(); const save = trpc.cms.settings.upsert.useMutation({ onSuccess: () => { toast.success("Website settings saved"); utils.cms.overview.invalidate(); }, onError: error => toast.error(error.message) }); const saveSeo = trpc.cms.seo.upsert.useMutation({ onSuccess: () => { toast.success("SEO record saved"); utils.cms.overview.invalidate(); }, onError: error => toast.error(error.message) }); const [selected, setSelected] = useState<any>(settings[0]); const [value, setValue] = useState(selected ? JSON.stringify(selected.value, null, 2) : "{}"); const [seoDraft, setSeoDraft] = useState({ path: seo[0]?.path || "/", title: seo[0]?.title || "", description: seo[0]?.description || "", canonicalUrl: seo[0]?.canonicalUrl || "", ogImageUrl: seo[0]?.ogImageUrl || "", indexable: seo[0]?.indexable ?? true }); const updateSelected = (setting: any) => { setSelected(setting); setValue(JSON.stringify(setting.value, null, 2)); }; const saveSettings = () => { try { save.mutate({ key: selected.key, label: selected.label, description: selected.description || undefined, value: JSON.parse(value) }); } catch { toast.error("Settings JSON must be valid before saving"); } }; return <div className="space-y-6"><section className="grid gap-6 lg:grid-cols-[.65fr_1.35fr]"><div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><p className="eyebrow">Super Admin</p><h2 className="mt-1 text-xl font-bold text-navy">Website settings</h2><div className="mt-5 grid gap-2">{settings.map(setting => <button key={setting.id} onClick={() => updateSelected(setting)} className={`rounded-xl px-4 py-3 text-left text-sm font-semibold ${selected?.id === setting.id ? "bg-navy text-white" : "bg-slate-50 text-slate-700 hover:bg-slate-100"}`}>{setting.label}</button>)}</div></div><div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">{selected ? <><h2 className="text-xl font-bold text-navy">{selected.label}</h2><p className="mt-2 text-sm text-slate-600">{selected.description}</p><Textarea className="mt-6 min-h-64 font-mono text-xs" value={value} onChange={event => setValue(event.target.value)} /><Button className="mt-4" onClick={saveSettings} disabled={save.isPending}><Save className="h-4 w-4" />Save settings</Button></> : <p className="text-slate-600">No settings available.</p>}</div></section><section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><p className="eyebrow">SEO management</p><h2 className="mt-1 text-xl font-bold text-navy">Page metadata</h2><p className="mt-2 text-sm text-slate-600">Set page titles, descriptions, canonical URLs, social images, and index controls for public routes.</p><div className="mt-6 grid gap-4 md:grid-cols-2"><Input value={seoDraft.path} onChange={event => setSeoDraft({ ...seoDraft, path: event.target.value })} placeholder="Path, e.g. /about" /><Input value={seoDraft.title} onChange={event => setSeoDraft({ ...seoDraft, title: event.target.value })} placeholder="SEO title" /><Textarea className="md:col-span-2" value={seoDraft.description} onChange={event => setSeoDraft({ ...seoDraft, description: event.target.value })} placeholder="Meta description" /><Input className="md:col-span-2" value={seoDraft.canonicalUrl} onChange={event => setSeoDraft({ ...seoDraft, canonicalUrl: event.target.value })} placeholder="Canonical URL (optional)" /><Input className="md:col-span-2" value={seoDraft.ogImageUrl} onChange={event => setSeoDraft({ ...seoDraft, ogImageUrl: event.target.value })} placeholder="Open Graph image URL (optional)" /><label className="flex items-center gap-2 text-sm font-semibold text-slate-700"><input type="checkbox" checked={seoDraft.indexable} onChange={event => setSeoDraft({ ...seoDraft, indexable: event.target.checked })} />Allow indexing</label></div><Button className="mt-5" onClick={() => saveSeo.mutate(seoDraft)} disabled={saveSeo.isPending}><Save className="h-4 w-4" />Save SEO record</Button></section></div>; }
